): CitationFormatResult | null {
  try {
    const stripped = stripJsonResponse(text);
    const candidate = extractFirstJsonObject(stripped) ?? stripped;
    const o = JSON.parse(candidate);
    if (typeof o.title === "string" && o.title.trim()) {
      const year =
