  // the project root, e.g. "/prompts/persona-system.md".
  const tryVariants = [
    name.endsWith(".md") ? name : `${name}.md`,
    `/prompts/${name.replace(/^\//, "")}${name.endsWith(".md") ? "" : ".md"}`,
    `/prompts/blocks/${name.replace(/^\//, "")}${name.endsWith(".md") ? "" : ".md"}`,
